  var CSS = "\n/* Layout: stat strip on top; hardware stage (left) with stage bar, caption, transport and the growing compiled circuit; input circuit and operation rules (right); one column on phones. */\n:host{all:initial;display:block;container-type:inline-size;\n  --bg:#e9edf2; --surface:#ffffff; --surface-2:#dde4ec; --chip:#f5f7fa; --ink:#15202b; --muted:#5a6b7e; --line:#b3bfcc;\n  --node:#e8edf3; --node-stroke:#8b9cb0; --qubit:#e8892b; --qubit-ink:#1b1100; --epr:#6b4cf0; --epr-soft:#e8e2ff;\n  --busy:#d63f4b; --ok:#1f9d63; --focus:#2563eb; --shadow:0 1px 2px rgba(21,32,43,.08);\n  --font-ui:\"IBM Plex Sans\",\"Helvetica Neue\",Arial,sans-serif;\n  --font-mono:\"IBM Plex Mono\",\"SFMono-Regular\",Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme:dark){:host(:not([theme=\"light\"])){\n  --bg:#0d1218; --surface:#151c25; --surface-2:#1e2834; --chip:#19222d; --ink:#e6edf5; --muted:#90a1b4; --line:#35455a;\n  --node:#243040; --node-stroke:#56697d; --qubit:#f2a24b; --qubit-ink:#1b1100; --epr:#a68cff; --epr-soft:#2a2350;\n  --busy:#ff6670; --ok:#3ecf8e; --focus:#60a5fa; --shadow:0 1px 2px rgba(0,0,0,.45); color-scheme:dark }}\n:host([theme=\"dark\"]){\n  --bg:#0d1218; --surface:#151c25; --surface-2:#1e2834; --chip:#19222d; --ink:#e6edf5; --muted:#90a1b4; --line:#35455a;\n  --node:#243040; --node-stroke:#56697d; --qubit:#f2a24b; --qubit-ink:#1b1100; --epr:#a68cff; --epr-soft:#2a2350;\n  --busy:#ff6670; --ok:#3ecf8e; --focus:#60a5fa; --shadow:0 1px 2px rgba(0,0,0,.45); color-scheme:dark }\n*{box-sizing:border-box}\n.dqc-body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font-ui);font-size:14px;line-height:1.45;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:14px 40px}\nh1,h2{margin:0;text-wrap:balance}\nh1{font-size:22px;font-weight:600;letter-spacing:-.01em}\nh2{font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\nh2 small{font-weight:500;text-transform:none;letter-spacing:0;margin-left:6px}\n.wrap{max-width:1480px;margin:0 auto;display:grid;gap:14px}\n.top{display:flex;flex-wrap:wrap;gap:14px 28px;align-items:flex-end;justify-content:space-between}\n.sub{margin:4px 0 0;color:var(--muted);max-width:70ch}\n.stats{display:flex;flex-wrap:wrap;gap:8px}\n.stat{background:var(--surface);border-radius:10px;padding:8px 12px;min-width:104px;box-shadow:var(--shadow)}\n.stat .k{display:block;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.stat .v{display:block;font:600 22px/1.15 var(--font-mono);font-variant-numeric:tabular-nums}\n.stat .v small{font-size:12px;color:var(--muted);font-weight:500}\n.stat .v.busy{color:var(--busy)}\n.grid{display:grid;grid-template-columns:minmax(0,2.3fr) minmax(300px,1fr);gap:14px;align-items:start}\n.card{background:var(--surface);border-radius:14px;box-shadow:var(--shadow);padding:14px;min-width:0}\n.side{display:grid;gap:14px;min-width:0}\n.stagebar{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:6px 16px;padding:2px 4px 8px}\n.sb-slot{font:600 18px var(--font-mono);font-variant-numeric:tabular-nums}\n.sb-step{margin-left:10px;color:var(--muted);font:500 13px var(--font-mono)}\n.sb-status{color:var(--muted);font-size:13px}\n.sb-status.busy{color:var(--busy)} .sb-status.ok{color:var(--ok)} .sb-status.bad{color:var(--busy)}\n#hw{width:100%;height:auto;display:block}\n.caption{margin-top:8px;padding:12px 16px;border-radius:10px;background:var(--surface-2);min-height:96px;display:grid;align-content:start;gap:9px}\n.cap-head{margin:0 0 -2px;font:600 10.5px var(--font-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.cap-body{margin:0;font-size:14.5px;line-height:1.5;max-width:90ch}\n.cap-list{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}\n.cap-list li{display:inline-flex;flex-wrap:wrap;align-items:center;gap:8px;padding:4px 10px 4px 5px;border-radius:8px;background:var(--surface);font-size:12.5px;line-height:1.3;box-shadow:var(--shadow)}\n.cap-list .what{font-weight:600}\n.cap-list .cdtxt{color:var(--busy);font:500 11.5px var(--font-mono)}\n.cap-list .why{color:var(--muted)}\n.tag{font:600 10.5px var(--font-mono);letter-spacing:.06em;text-transform:uppercase;padding:3px 7px;border-radius:5px;white-space:nowrap;color:#fff;background:var(--muted)}\n.tag.swap{background:var(--qubit);color:var(--qubit-ink)} .tag.score{background:var(--ok)} .tag.gen,.tag.eprok,.tag.tq,.tag.tg{background:var(--epr)} .tag.genfail{background:var(--busy)}\n.tag.wait,.tag.next{background:var(--surface);color:var(--muted);border:1px solid var(--line)}\n.transport{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:10px}\n.transport button{font:600 13px var(--font-ui);color:var(--ink);background:var(--surface-2);border:1px solid transparent;border-radius:8px;padding:7px 11px;cursor:pointer;min-width:40px}\n.transport button:hover{border-color:var(--line)}\n.transport button:focus-visible,.transport select:focus-visible{outline:2px solid var(--focus);outline-offset:2px}\n.transport button.primary{background:var(--ink);color:var(--surface);min-width:84px}\n.transport select{font:13px var(--font-ui);color:var(--ink);background:var(--surface-2);border:1px solid transparent;border-radius:8px;padding:7px 8px}\n.transport label.opt{display:inline-flex;align-items:center;gap:6px;color:var(--muted);font-size:12.5px;margin-left:4px}\n.transport .run{margin-left:auto;color:var(--muted);font:500 12px var(--font-mono)}\n.tlhead{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:6px 16px;margin-top:16px}\n.timeline{overflow-x:auto;margin-top:8px;border-radius:10px;background:var(--surface-2);padding:6px 4px}\n#tl{display:block;max-width:none}\n.tl-wire{stroke:var(--line);stroke-width:1.2} .tl-wire.link{stroke:var(--epr);stroke-dasharray:3 3;opacity:.75}\n.tl-lab{font:500 10px var(--font-mono);fill:var(--muted)} .tl-lab.link{fill:var(--epr)}\n.tl-col{fill:transparent;cursor:pointer} .tl-col:hover{fill:color-mix(in srgb,var(--ink) 7%,transparent)}\n.tl-col.cur{fill:color-mix(in srgb,var(--qubit) 18%,transparent)}\n.tl-col.drain{fill:color-mix(in srgb,var(--busy) 6%,transparent)} .tl-col.drain.cur{fill:color-mix(in srgb,var(--busy) 15%,transparent)}\n.tl-t{font:500 9.5px var(--font-mono);fill:var(--muted);pointer-events:none} .tl-t.cur{fill:var(--ink);font-weight:600}\n.tl-note{font:500 8.5px var(--font-mono);fill:var(--muted);pointer-events:none} .tl-note.epr{fill:var(--epr)}\n.tl-busy{stroke:var(--busy);stroke-width:5;stroke-linecap:round;opacity:.26}\n.tl-busy.gen{stroke:var(--epr);stroke-width:3.5;stroke-linecap:butt;stroke-dasharray:4 3;opacity:.6}\n.tl-ev{cursor:pointer}\n.tl-ev .s{stroke:var(--ok);stroke-width:1.8;fill:none} .tl-ev .f{fill:var(--ok)} .tl-ev .h{fill:var(--surface)}\n.tl-ev .d{stroke:var(--epr);stroke-width:1.2;stroke-dasharray:2.5 2.5;fill:none}\n.tl-ev.swap .s{stroke:var(--qubit)} .tl-ev.tg .s,.tl-ev.tq .s,.tl-ev.gen .s,.tl-ev.eprok .s{stroke:var(--epr)} .tl-ev.tg .f,.tl-ev.tq .f,.tl-ev.gen .f,.tl-ev.eprok .f{fill:var(--epr)} .tl-ev.genfail .s{stroke:var(--busy)}\n.legend{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:10px;color:var(--muted);font-size:12px}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend svg{width:22px;height:22px;flex:none}\n#circ{width:100%;height:auto;display:block;margin-top:8px}\n.rules{display:grid;gap:9px;margin-top:10px}\n.rule{display:grid;grid-template-columns:auto 1fr;gap:4px 10px;align-items:start;font-size:12.5px;line-height:1.4}\n.rule .tag{margin-top:1px}\n.rule b{font-weight:600}\n.rule .cd{display:block;color:var(--busy);font:500 12px var(--font-mono);margin-top:2px}\n.rules-note{margin:6px 0 0;color:var(--muted);font-size:12.5px}\n/* hardware stage */\n.chip{fill:var(--chip);stroke:var(--line);stroke-width:1}\n.chiplabel{font:600 11.5px var(--font-ui);fill:var(--muted);letter-spacing:.08em;text-transform:uppercase}\n.edge{stroke:var(--line);stroke-width:4;stroke-linecap:round;transition:stroke .2s,stroke-width .2s}\n.edge.quantum{stroke:var(--epr);stroke-width:2.5;stroke-dasharray:7 6}\n.edge.hot{stroke:var(--ok);stroke-width:7}\n.edge.warm{stroke:var(--qubit);stroke-width:6}\n.linklabel{font:10.5px var(--font-mono);fill:var(--epr)}\n.node{fill:var(--node);stroke:var(--node-stroke);stroke-width:1.5}\n.node.link{stroke:var(--epr);stroke-dasharray:3 2.5}\n.pid{font:10px var(--font-mono);fill:var(--muted)}\n.ring{fill:none;stroke:var(--busy);stroke-width:3.5;stroke-linecap:round}\n.cd rect{fill:var(--busy)} .cd text{font:600 10.5px var(--font-mono);fill:#fff}\n.cd{transform-box:fill-box;transform-origin:center}\n.cd.pop{animation:pop .5s ease-out}\n@keyframes pop{0%{transform:scale(1)}40%{transform:scale(1.6)}100%{transform:scale(1)}}\n.free{fill:none;stroke:var(--ok);stroke-width:3}\n.token{pointer-events:none}\n.token.qubit circle{fill:var(--qubit);stroke:var(--surface);stroke-width:2}\n.token.qubit text{font:600 11.5px var(--font-mono);fill:var(--qubit-ink)}\n.token.epr circle{fill:var(--epr-soft);stroke:var(--epr);stroke-width:2}\n.token.epr text{font:600 10px var(--font-mono);fill:var(--epr)}\n.token.attempt circle{fill:var(--node);stroke:var(--epr);stroke-width:2;stroke-dasharray:4 3;animation:crawl 1.4s linear infinite}\n.token.attempt text{font:600 12.5px var(--font-mono);fill:var(--epr)}\n@keyframes crawl{to{stroke-dashoffset:-14}}\n.ent{fill:none;stroke:var(--epr);stroke-width:2;stroke-dasharray:5 5;animation:flow 1.1s linear infinite}\n.ent.pending{stroke-dasharray:4 6;opacity:.5}\n@keyframes flow{to{stroke-dashoffset:-20}}\n.pill text{font:600 12.5px var(--font-mono);fill:#fff;letter-spacing:.04em}\n.pill rect{fill:var(--muted)}\n.pill.swap rect{fill:var(--qubit)} .pill.swap text{fill:var(--qubit-ink)}\n.pill.score rect{fill:var(--ok)} .pill.gen rect,.pill.eprok rect,.pill.tq rect,.pill.tg rect{fill:var(--epr)} .pill.genfail rect{fill:var(--busy)}\n.pill.idle rect{fill:var(--surface-2);stroke:var(--line)} .pill.idle text{fill:var(--muted)}\n.fx-label{font:600 12px var(--font-mono);fill:var(--ink)}\n.fx-label.ok{fill:var(--ok)} .fx-label.bad{fill:var(--busy)} .fx-label.epr{fill:var(--epr)}\n.photon{fill:var(--epr)}\n.failring{fill:none;stroke:var(--busy);stroke-width:3}\n.tgarc{fill:none;stroke:var(--epr);stroke-width:3;stroke-linecap:round}\n.ghost{fill:none;stroke:var(--qubit);stroke-width:1.5;stroke-dasharray:3 3}\n/* circuit panel */\n.wire{stroke:var(--line);stroke-width:1.5}\n.qlabel{font:11px var(--font-mono);fill:var(--muted)}\n.gate .s{stroke:var(--muted);stroke-width:2} .gate .f{fill:var(--muted)} .gate .h{fill:var(--surface)}\n.gate.pending{opacity:.5}\n.gate.frontier .s{stroke:var(--qubit)} .gate.frontier .f{fill:var(--qubit)}\n.gate.done .s{stroke:var(--ok)} .gate.done .f{fill:var(--ok)}\n.gate.active .s{stroke:var(--ok);stroke-width:3.5}\n.gate .lab{font:500 9.5px var(--font-mono);fill:var(--muted)}\n.gate .lab.slot{fill:var(--ok)} .gate .lab.slot.remote{fill:var(--epr);font-weight:600}\n.gate .remring{fill:none;stroke:var(--epr);stroke-width:1.5;stroke-dasharray:2 2}\n@media (prefers-reduced-motion:reduce){.ent{animation:none}.token.attempt circle{animation:none}.edge{transition:none}.cd.pop{animation:none}}\n@container (max-width:900px){.grid{grid-template-columns:1fr}.stat{min-width:88px}.stat .v{font-size:18px}}\n\n:host([hidden]){display:none}:host(:focus){outline:none}:host(:focus-visible){outline:2px solid var(--focus);outline-offset:2px}\n";
  var HTML = "<div class=\"dqc-body\">\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div>\n      <h1>DQC Compiler Environment</h1>\n      <p class=\"sub\">Two 16-qubit QPUs joined by one quantum link, which can generate an EPR pair between them with a probability that depends on the entanglement source. The compiler has to run the input circuit on the right on this hardware. Time is counted in slots, like the clock cycles of a CPU: one slot is the time of the smallest operation, and every operation keeps its qubits busy for a number of slots. Press Play to watch the compiler decide slot by slot.</p>\n    </div>\n    <div class=\"stats\" aria-live=\"polite\">\n      <div class=\"stat\"><span class=\"k\">Time slot</span><span class=\"v\" id=\"st-slot\">0</span></div>\n      <div class=\"stat\"><span class=\"k\">Gates done</span><span class=\"v\" id=\"st-gates\">0 <small>/ 8</small></span></div>\n      <div class=\"stat\"><span class=\"k\">EPR pairs</span><span class=\"v\" id=\"st-epr\">0 <small>used</small></span></div>\n      <div class=\"stat\"><span class=\"k\">Cooling down</span><span class=\"v\" id=\"st-busy\">0 <small>qubits</small></span></div>\n    </div>\n  </header>\n  <main class=\"grid\">\n    <section class=\"card hw\">\n      <div class=\"stagebar\">\n        <div><span class=\"sb-slot\" id=\"sb-slot\">t = 0</span><span class=\"sb-step\" id=\"sb-step\">initial placement</span></div>\n        <div class=\"sb-status\" id=\"sb-status\">no operation issued yet</div>\n      </div>\n      <svg id=\"hw\" role=\"img\" aria-label=\"Two 16-qubit coupling graphs joined by a quantum link, with the circuit's qubits, EPR halves and cooldown rings drawn on the physical qubits\"></svg>\n      <div class=\"caption\">\n        <h3 class=\"cap-head\" id=\"cap-head\">Initial placement</h3>\n        <p class=\"cap-body\" id=\"cap-body\"></p>\n        <ul class=\"cap-list\" id=\"cap-list\"></ul>\n      </div>\n      <div class=\"transport\">\n        <button id=\"btn-first\" title=\"Initial state, t = 0 (Home)\">\u23ee</button>\n        <button id=\"btn-prev\" title=\"Previous slot (\u2190)\">\u25c0</button>\n        <button id=\"btn-play\" class=\"primary\" title=\"Play / pause (Space)\">Play</button>\n        <button id=\"btn-next\" title=\"Next slot (\u2192)\">\u25b6</button>\n        <button id=\"btn-last\" title=\"Compile to the end (End)\">\u23ed</button>\n        <select id=\"speed\" aria-label=\"Playback speed\"><option value=\"0.5\">0.5\u00d7 slower</option><option value=\"0.75\">0.75\u00d7</option><option value=\"1\" selected>1\u00d7</option><option value=\"1.5\">1.5\u00d7</option><option value=\"2\">2\u00d7</option><option value=\"3\">3\u00d7</option><option value=\"4\">4\u00d7 faster</option></select>\n        <label class=\"opt\">EPR success <select id=\"pgen\" aria-label=\"EPR generation success probability\"><option value=\"0.95\" selected>p = 0.95</option><option value=\"0.8\">p = 0.8</option><option value=\"0.5\">p = 0.5</option><option value=\"0.3\">p = 0.3</option></select></label>\n        <span class=\"run\" id=\"run-note\">run 1</span>\n      </div>\n      <div class=\"tlhead\"><h2>Compiled circuit <small>the compiler's output, one column per time slot</small></h2></div>\n      <div class=\"timeline\" id=\"tlwrap\"><svg id=\"tl\" role=\"img\" aria-label=\"The compiled circuit as a timeline: one wire per circuit qubit plus the quantum link, with the operations issued in each time slot and the slots each qubit stays busy\"></svg></div>\n      <div class=\"legend\">\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"11\" y1=\"5\" x2=\"11\" y2=\"16\" stroke=\"var(--ok)\" stroke-width=\"1.8\"/><circle cx=\"11\" cy=\"5\" r=\"3\" fill=\"var(--ok)\"/><circle cx=\"11\" cy=\"16\" r=\"4.5\" fill=\"var(--surface)\" stroke=\"var(--ok)\" stroke-width=\"1.8\"/></svg>local CNOT</span>\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"11\" y1=\"5\" x2=\"11\" y2=\"16\" stroke=\"var(--epr)\" stroke-width=\"1.8\"/><circle cx=\"11\" cy=\"5\" r=\"3\" fill=\"var(--epr)\"/><circle cx=\"11\" cy=\"16\" r=\"4.5\" fill=\"var(--surface)\" stroke=\"var(--epr)\" stroke-width=\"1.8\"/></svg>gate teleportation</span>\n        <span><svg viewBox=\"0 0 22 22\"><path d=\"M11 4 L17 11 L11 18 L5 11 Z\" fill=\"var(--epr)\"/></svg>state teleportation</span>\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"6\" y1=\"6\" x2=\"16\" y2=\"16\" stroke=\"var(--qubit)\" stroke-width=\"2\"/><line x1=\"6\" y1=\"16\" x2=\"16\" y2=\"6\" stroke=\"var(--qubit)\" stroke-width=\"2\"/></svg>SWAP</span>\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"9\" y1=\"11\" x2=\"21\" y2=\"11\" stroke=\"var(--epr)\" stroke-width=\"3.5\" stroke-dasharray=\"4 3\" opacity=\".6\"/><circle cx=\"5\" cy=\"11\" r=\"4\" fill=\"var(--surface)\" stroke=\"var(--epr)\" stroke-width=\"1.8\"/></svg>EPR attempt (5 slots)</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"5\" fill=\"var(--epr)\"/></svg>attempt succeeded \u00b7 pair ready</span>\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"6\" y1=\"6\" x2=\"16\" y2=\"16\" stroke=\"var(--busy)\" stroke-width=\"2\"/><line x1=\"6\" y1=\"16\" x2=\"16\" y2=\"6\" stroke=\"var(--busy)\" stroke-width=\"2\"/></svg>attempt failed</span>\n        <span><svg viewBox=\"0 0 22 22\"><line x1=\"3\" y1=\"11\" x2=\"19\" y2=\"11\" stroke=\"var(--busy)\" stroke-width=\"5\" stroke-linecap=\"round\" opacity=\".35\"/></svg>busy (cooldown)</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"8\" fill=\"var(--qubit)\"/></svg>circuit qubit</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"8\" fill=\"var(--epr-soft)\" stroke=\"var(--epr)\" stroke-width=\"2\"/></svg>EPR half</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"8\" fill=\"var(--node)\" stroke=\"var(--epr)\" stroke-width=\"2\" stroke-dasharray=\"3 2.5\"/><text x=\"11\" y=\"11\" text-anchor=\"middle\" dy=\"0.35em\" style=\"font:600 10px var(--font-mono);fill:var(--epr)\">?</text></svg>attempt in flight</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"8\" fill=\"var(--node)\" stroke=\"var(--epr)\" stroke-width=\"1.5\" stroke-dasharray=\"3 2.5\"/></svg>link qubit</span>\n        <span><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"8\" fill=\"none\" stroke=\"var(--busy)\" stroke-width=\"3\" stroke-dasharray=\"30 50\" transform=\"rotate(-90 11 11)\"/><rect x=\"11\" y=\"11\" width=\"10\" height=\"8\" rx=\"2\" fill=\"var(--busy)\"/></svg>cooldown (slots left)</span>\n      </div>\n    </section>\n    <aside class=\"side\">\n      <section class=\"card\">\n        <h2>Input circuit <small>7 qubits \u00b7 8 CNOTs</small></h2>\n        <svg id=\"circ\" role=\"img\" aria-label=\"The eight CNOT gates of the input circuit drawn on seven qubit wires; each gate is marked pending, ready, or done with the slot it executed in\"></svg>\n      </section>\n      <section class=\"card\">\n        <h2>Operations and cooldowns</h2>\n        <p class=\"rules-note\">The cooldowns are representative: each one is essentially how many slots of clock time the operation takes. An operation is only issued when every qubit it involves is free, so nothing ever runs on a qubit that is still cooling down.</p>\n        <div class=\"rules\" id=\"rules\"></div>\n      </section>\n    </aside>\n  </main>\n</div>\n</div>";
