      await tween(d, t => { const s = 1 + 0.3 * Math.sin(Math.PI * Math.min(1, t * 1.6)); toks.forEach(tk => setPos(tk, tk.x, tk.y, s)); }, seq);
      toks.forEach(tk => setPos(tk, tk.x, tk.y, 1)); e.classList.remove('hot');
